import{_ as i,c as t,o as n,ae as l}from"./chunks/framework.DMK_uHmU.js";const r="/help-center/assets/blueprint-ai-settings.B6yUtl2t.png",o="/help-center/assets/blueprint-sharing.CBGaoL4G.png",a="/help-center/assets/blueprint-actions.BpVDZ8a6.png",b=JSON.parse('{"title":"AI Blueprint Configuration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"Administration/AI-Management/Blueprints/blueprint-settings.md","filePath":"Administration/AI-Management/Blueprints/blueprint-settings.md"}'),s={name:"Administration/AI-Management/Blueprints/blueprint-settings.md"};function u(p,e,c,d,h,g){return n(),t("div",null,e[0]||(e[0]=[l('<h1 id="ai-blueprint-configuration-guide" tabindex="-1">AI Blueprint Configuration Guide <a class="header-anchor" href="#ai-blueprint-configuration-guide" aria-label="Permalink to &quot;AI Blueprint Configuration Guide&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>AI Blueprints allow administrators and content creators to define customized AI experiences with specific knowledge bases, web resources, instructions, and conversation flows. Blueprints serve as reusable configurations that can be shared with users to ensure consistent AI interactions tailored to specific needs or departments.</p><h2 id="accessing-blueprint-configuration" tabindex="-1">Accessing Blueprint Configuration <a class="header-anchor" href="#accessing-blueprint-configuration" aria-label="Permalink to &quot;Accessing Blueprint Configuration&quot;">​</a></h2><p>The Blueprint configuration interface is accessible to users with specific roles:</p><ul><li>Admin</li><li>Content</li><li>Manager</li></ul><p>To access Blueprint configuration:</p><ol><li>Navigate to the Blueprint management section in the system</li><li>Select an existing Blueprint to edit, or</li><li>Create a new Blueprint using the &quot;Add Blueprint&quot; button</li></ol><h2 id="blueprint-interface-overview" tabindex="-1">Blueprint Interface Overview <a class="header-anchor" href="#blueprint-interface-overview" aria-label="Permalink to &quot;Blueprint Interface Overview&quot;">​</a></h2><p>The Blueprint interface consists of these key components:</p><ol><li><strong>Navigation Tabs</strong>: Blueprint, AI Settings, Share</li><li><strong>Action Buttons</strong>: Save, Run, Actions menu</li><li><strong>Configuration Area</strong>: Main content area that changes based on selected tab</li><li><strong>Preview Pane</strong>: Real-time visualization of Blueprint appearance</li></ol><h2 id="blueprint-configuration-tabs" tabindex="-1">Blueprint Configuration Tabs <a class="header-anchor" href="#blueprint-configuration-tabs" aria-label="Permalink to &quot;Blueprint Configuration Tabs&quot;">​</a></h2><h3 id="blueprint-tab" tabindex="-1">Blueprint Tab <a class="header-anchor" href="#blueprint-tab" aria-label="Permalink to &quot;Blueprint Tab&quot;">​</a></h3><p>The Blueprint tab contains basic configuration settings:</p><ul><li>Name and description</li><li>Visual identifiers (initials)</li><li>Topics and tags</li><li>Security settings</li><li>Visibility options</li><li>Conversation starters</li></ul><h3 id="ai-settings-tab" tabindex="-1">AI Settings Tab <a class="header-anchor" href="#ai-settings-tab" aria-label="Permalink to &quot;AI Settings Tab&quot;">​</a></h3><p>The AI Settings tab contains AI behavior configuration:</p><ul><li>System instructions</li><li>AI model selection</li><li>Response style preferences</li><li>Content sources configuration</li><li>Knowledge base selection</li><li>Web integration settings</li></ul><p><img src="'+r+'" alt="homepage"></p><h3 id="share-tab" tabindex="-1">Share Tab <a class="header-anchor" href="#share-tab" aria-label="Permalink to &quot;Share Tab&quot;">​</a></h3><p>The Share tab controls access and permissions:</p><ul><li>Group assignments</li><li>Universal link generation</li><li>Ownership management</li></ul><p><img src="'+o+'" alt="homepage"></p><h2 id="basic-blueprint-information" tabindex="-1">Basic Blueprint Information <a class="header-anchor" href="#basic-blueprint-information" aria-label="Permalink to &quot;Basic Blueprint Information&quot;">​</a></h2><h3 id="name-and-description" tabindex="-1">Name and Description <a class="header-anchor" href="#name-and-description" aria-label="Permalink to &quot;Name and Description&quot;">​</a></h3><p>The Blueprint name and description are fundamental identifiers:</p><ol><li><p><strong>Name</strong> (Required):</p><ul><li>Clear, descriptive title that reflects purpose</li><li>Used as primary identifier throughout the system</li><li>Must be unique within the system</li><li>Examples: &quot;Customer Support Assistant&quot;, &quot;HR Policy Guide&quot;</li></ul></li><li><p><strong>Initials</strong> (Required):</p><ul><li>Two-letter identifier used in the Blueprint avatar</li><li>Automatically generated from name but can be customized</li><li>Used in visual representations throughout the system</li></ul></li><li><p><strong>Description</strong>:</p><ul><li>Comprehensive explanation of the Blueprint&#39;s purpose</li><li>Helps users understand when to use this Blueprint</li><li>Appears in the Blueprint selection interface</li><li>Should explain capabilities and limitations</li></ul></li></ol><h3 id="topic-and-tags" tabindex="-1">Topic and Tags <a class="header-anchor" href="#topic-and-tags" aria-label="Permalink to &quot;Topic and Tags&quot;">​</a></h3><p>Topics and tags help organize and categorize Blueprints:</p><ol><li><p><strong>Topic</strong>:</p><ul><li>Single selection from predefined list</li><li>Used for high-level categorization</li><li>Helps filter Blueprints by subject area</li></ul></li><li><p><strong>Tags</strong>:</p><ul><li>Multiple selections from predefined list</li><li>Can create new tags on demand</li><li>Used for more granular categorization</li><li>Facilitates Blueprint discovery</li></ul></li></ol><h3 id="security-settings" tabindex="-1">Security Settings <a class="header-anchor" href="#security-settings" aria-label="Permalink to &quot;Security Settings&quot;">​</a></h3><p>Several toggles control Blueprint security:</p><ol><li><p><strong>Secret</strong>:</p><ul><li>When enabled, hides Blueprint settings from non-owners</li><li>Users can still use the Blueprint but cannot view configuration</li><li>Useful for protecting proprietary instructions or data sources</li></ul></li><li><p><strong>Allow Copies</strong>:</p><ul><li>When enabled, allows other users to create derivative Blueprints</li><li>When disabled, prevents duplication of your Blueprint</li><li>Useful for template distribution and knowledge sharing</li></ul></li></ol><h3 id="visibility-options" tabindex="-1">Visibility Options <a class="header-anchor" href="#visibility-options" aria-label="Permalink to &quot;Visibility Options&quot;">​</a></h3><p>Control where and how your Blueprint appears:</p><ol><li><p><strong>Publish in Quick List</strong>:</p><ul><li>When enabled, Blueprint appears in main AI selector dropdown</li><li>Provides quick access for frequently used Blueprints</li><li>Recommended for widely used Blueprints</li></ul></li><li><p><strong>Publish on Home Page</strong>:</p><ul><li>When enabled, Blueprint appears on users&#39; home pages</li><li>Increases visibility and discovery</li><li>Use for important or new Blueprints that need promotion</li></ul></li></ol><h2 id="conversation-starters" tabindex="-1">Conversation Starters <a class="header-anchor" href="#conversation-starters" aria-label="Permalink to &quot;Conversation Starters&quot;">​</a></h2><p>Conversation starters are predefined prompts that help guide users to effective interactions.</p><h3 id="creating-conversation-starters" tabindex="-1">Creating Conversation Starters <a class="header-anchor" href="#creating-conversation-starters" aria-label="Permalink to &quot;Creating Conversation Starters&quot;">​</a></h3><p>To add conversation starters:</p><ol><li>Click the &quot;+&quot; button next to the Conversation Starters header</li><li>For each starter, provide: <ul><li><strong>Title</strong>: Short, action-oriented prompt (e.g., &quot;Find policy information&quot;)</li><li><strong>Instructions</strong>: Full prompt that will be sent to the AI</li><li><strong>LaunchPad</strong>: Toggle to show/hide in the LaunchPad interface</li></ul></li></ol><h3 id="managing-launchpad-settings" tabindex="-1">Managing Launchpad Settings <a class="header-anchor" href="#managing-launchpad-settings" aria-label="Permalink to &quot;Managing Launchpad Settings&quot;">​</a></h3><p>The LaunchPad is a quick access interface for conversation starters:</p><ul><li>Enable LaunchPad for frequently used conversation flows</li><li>LaunchPad items appear as buttons on the Blueprint interface</li><li>Use descriptive titles for clear user navigation</li></ul><h3 id="reordering-starters" tabindex="-1">Reordering Starters <a class="header-anchor" href="#reordering-starters" aria-label="Permalink to &quot;Reordering Starters&quot;">​</a></h3><p>Conversation starters can be reordered using drag-and-drop:</p><ol><li>Hover over the conversation starter row</li><li>Use the vertical ellipsis (⋮⋮) handle on the left to drag</li><li>Drop in the desired position</li><li>Order is preserved when the Blueprint is saved</li></ol><h2 id="ai-configuration" tabindex="-1">AI Configuration <a class="header-anchor" href="#ai-configuration" aria-label="Permalink to &quot;AI Configuration&quot;">​</a></h2><h3 id="instructions" tabindex="-1">Instructions <a class="header-anchor" href="#instructions" aria-label="Permalink to &quot;Instructions&quot;">​</a></h3><p>Instructions tell the AI how to behave and respond:</p><ol><li><p><strong>System Instructions</strong>:</p><ul><li>Detailed guidance for the AI&#39;s behavior</li><li>Define scope, tone, limitations, and resources</li><li>Can include role-specific instructions</li><li>Supports rich formatting for clarity</li><li>Maximum 30,000 characters</li></ul></li><li><p><strong>Best Practices for Instructions</strong>:</p><ul><li>Be specific about the AI&#39;s role and purpose</li><li>Define boundaries clearly (what it should/shouldn&#39;t do)</li><li>Specify preferred response format and style</li><li>Include domain-specific guidance when relevant</li></ul></li></ol><h3 id="model-selection" tabindex="-1">Model Selection <a class="header-anchor" href="#model-selection" aria-label="Permalink to &quot;Model Selection&quot;">​</a></h3><p>Choose the AI foundation model that powers the Blueprint:</p><ol><li><p><strong>Haiku</strong>:</p><ul><li>Faster responses</li><li>More economical</li><li>General knowledge capabilities</li><li>Best for straightforward questions and tasks</li></ul></li><li><p><strong>Sonnet</strong>:</p><ul><li>More advanced reasoning</li><li>Handles complex queries</li><li>Better contextual understanding</li><li>Higher cost but better for specialized tasks</li></ul></li></ol><h3 id="ai-mode" tabindex="-1">AI Mode <a class="header-anchor" href="#ai-mode" aria-label="Permalink to &quot;AI Mode&quot;">​</a></h3><p>Select the operational mode for the AI:</p><ol><li><p><strong>Question &amp; Answers</strong>:</p><ul><li>Fast responses focused on direct answers</li><li>Searches only through specified knowledge bases and content</li><li>Best for factual information retrieval</li></ul></li><li><p><strong>Agentic</strong>:</p><ul><li>Comprehensive approach using multiple tools and sources</li><li>Longer processing time but more thorough results</li><li>Best for complex problems requiring multiple steps</li></ul></li><li><p><strong>Tools</strong>:</p><ul><li>Advanced mode for complex workflows</li><li>Uses Chain of Thought processing</li><li>Best for specialized applications with multiple data sources</li><li>Requires more detailed configuration</li></ul></li></ol><h3 id="response-controls" tabindex="-1">Response Controls <a class="header-anchor" href="#response-controls" aria-label="Permalink to &quot;Response Controls&quot;">​</a></h3><p>Several settings adjust how the AI responds:</p><ol><li><p><strong>LLM General Knowledge</strong>:</p><ul><li>When enabled, allows AI to use its built-in knowledge</li><li>When disabled, AI relies only on specified content sources</li><li>Use off setting when answers must come only from approved content</li></ul></li><li><p><strong>Cite Sources</strong>:</p><ul><li>When enabled, AI provides references for information</li><li>Enhances credibility and verifiability</li><li>Recommended for research or compliance scenarios</li></ul></li><li><p><strong>Profanity</strong>:</p><ul><li>When enabled, allows AI to use potentially offensive language</li><li>When disabled (default), filters offensive content</li><li>Consider your audience and use case when configuring</li></ul></li></ol><h3 id="web-integration" tabindex="-1">Web Integration <a class="header-anchor" href="#web-integration" aria-label="Permalink to &quot;Web Integration&quot;">​</a></h3><p>Control how the AI interacts with external web resources:</p><ol><li><p><strong>Live Web Lookup</strong>:</p><ul><li>When enabled, allows AI to search the internet for current information</li><li>Set number of results (1-25) to control breadth of search</li><li>Useful for time-sensitive or rapidly changing topics</li></ul></li><li><p><strong>Live News Lookup</strong>:</p><ul><li>When enabled, searches current news articles</li><li>Configure number of results (1-50) and time period (days)</li><li>Best for current events and trending topics</li></ul></li></ol><h3 id="knowledge-base-configuration" tabindex="-1">Knowledge Base Configuration <a class="header-anchor" href="#knowledge-base-configuration" aria-label="Permalink to &quot;Knowledge Base Configuration&quot;">​</a></h3><p>Configure how the AI uses your organization&#39;s knowledge:</p><ol><li><p><strong>Knowledge Base Selection</strong>:</p><ul><li>Choose specific knowledge bases for the Blueprint</li><li>Filter and search available KBs using the search box</li><li>Selected KBs appear as blue chips in the preview area</li></ul></li><li><p><strong>Content Selection</strong>:</p><ul><li>Choose specific content items (documents, files) for the Blueprint</li><li>Filter and search available content using the search box</li><li>Selected content appears as white chips in the preview area</li></ul></li><li><p><strong>Search Parameters</strong>:</p><ul><li><strong>KB Search Results</strong>: Number of records to retrieve (1-500)</li><li><strong>KB Min Score Results</strong>: Minimum relevance threshold (percentage)</li><li>Higher thresholds provide more relevant but fewer results</li></ul></li></ol><h3 id="web-pages-configuration" tabindex="-1">Web Pages Configuration <a class="header-anchor" href="#web-pages-configuration" aria-label="Permalink to &quot;Web Pages Configuration&quot;">​</a></h3><p>Add specific web pages as knowledge sources:</p><ol><li><p><strong>Adding Web Pages</strong>:</p><ul><li>Enter full URLs including https://</li><li>Limited to 15 pages per Blueprint</li><li>AI will retrieve and use content from these pages</li></ul></li><li><p><strong>Managing Web Pages</strong>:</p><ul><li>Remove pages using the trash icon</li><li>Pages are processed each time the Blueprint is used</li><li>Ensure pages are accessible and contain relevant content</li></ul></li></ol><h2 id="sharing-and-access-control" tabindex="-1">Sharing and Access Control <a class="header-anchor" href="#sharing-and-access-control" aria-label="Permalink to &quot;Sharing and Access Control&quot;">​</a></h2><h3 id="group-assignments" tabindex="-1">Group Assignments <a class="header-anchor" href="#group-assignments" aria-label="Permalink to &quot;Group Assignments&quot;">​</a></h3><p>Control which users can access the Blueprint:</p><ol><li><p><strong>Group Selection</strong>:</p><ul><li>Choose from existing groups in the system</li><li>Multiple groups can be selected</li><li>Only users belonging to selected groups will see this Blueprint</li><li>No groups selected means no users can access the Blueprint</li></ul></li><li><p><strong>Access Control Strategy</strong>:</p><ul><li>Department-based: Assign to department-specific groups</li><li>Role-based: Assign to groups based on job functions</li><li>Project-based: Assign to temporary project teams</li></ul></li></ol><h3 id="universal-links" tabindex="-1">Universal Links <a class="header-anchor" href="#universal-links" aria-label="Permalink to &quot;Universal Links&quot;">​</a></h3><p>Create shareable links to the Blueprint:</p><ol><li><strong>Universal Link</strong>: <ul><li>Automatically generated based on Blueprint ID</li><li>Can be copied and shared with authorized users</li><li>Recipients must still have group access to use the Blueprint</li><li>Format: <code>https://[domain]/ulink/[blueprint_id]</code></li></ul></li></ol><h3 id="ownership-management" tabindex="-1">Ownership Management <a class="header-anchor" href="#ownership-management" aria-label="Permalink to &quot;Ownership Management&quot;">​</a></h3><p>Manage who can edit and administer the Blueprint:</p><ol><li><p><strong>Adding Owners</strong>:</p><ul><li>Search for users by name or username</li><li>Added owners have full edit rights to the Blueprint</li><li>Owners can modify settings, content sources, and sharing</li></ul></li><li><p><strong>Removing Owners</strong>:</p><ul><li>Click the trash icon next to an owner to remove them</li><li>At least one owner is required</li><li>Owners should be limited to necessary personnel</li></ul></li></ol><h2 id="blueprint-management" tabindex="-1">Blueprint Management <a class="header-anchor" href="#blueprint-management" aria-label="Permalink to &quot;Blueprint Management&quot;">​</a></h2><h3 id="saving-blueprints" tabindex="-1">Saving Blueprints <a class="header-anchor" href="#saving-blueprints" aria-label="Permalink to &quot;Saving Blueprints&quot;">​</a></h3><p>To save a Blueprint:</p><ol><li>Click the &quot;Save&quot; button in the top-right corner</li><li>All settings across all tabs are saved</li><li>The button is outlined when there are no changes</li><li>The button is solid when there are unsaved changes</li></ol><h3 id="blueprint-actions" tabindex="-1">Blueprint Actions <a class="header-anchor" href="#blueprint-actions" aria-label="Permalink to &quot;Blueprint Actions&quot;">​</a></h3><p>The Actions menu provides additional operations:</p><ol><li><strong>Save Blueprint</strong>: Save current changes</li><li><strong>Save As New Blueprint</strong>: Create a copy with a new name</li><li><strong>Delete Blueprint</strong>: Remove the Blueprint entirely</li><li><strong>Enable/Disable Blueprint</strong>: Toggle availability</li><li><strong>Change Owner</strong>: Navigate to ownership management</li><li><strong>Create New Blueprint</strong>: Start fresh with default settings</li><li><strong>Import/Export Blueprint</strong>: Share configurations between systems</li></ol><p><img src="'+a+'" alt="homepage"></p><h3 id="import-export" tabindex="-1">Import/Export <a class="header-anchor" href="#import-export" aria-label="Permalink to &quot;Import/Export&quot;">​</a></h3><p>Share Blueprint configurations between environments:</p><ol><li><p><strong>Exporting</strong>:</p><ul><li>Select &quot;Export Blueprint&quot; from the Actions menu</li><li>A .blueprint file is saved to your browser downloads</li><li>Personal settings (IDs, owners) are removed during export</li></ul></li><li><p><strong>Importing</strong>:</p><ul><li>Select &quot;Import Blueprint&quot; from the Actions menu</li><li>Upload a .blueprint file</li><li>Review and configure group permissions, topics, and ownership</li><li>Secure Blueprints cannot be exported</li></ul></li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><p>For optimal Blueprint configuration:</p><ol><li><p><strong>Naming Conventions</strong>:</p><ul><li>Use descriptive names that clearly communicate purpose</li><li>Be consistent across related Blueprints</li><li>Consider including department/function in the name</li></ul></li><li><p><strong>Instructions</strong>:</p><ul><li>Be specific about the AI&#39;s purpose and limitations</li><li>Include sample dialogues for complex interactions</li><li>Review and refine based on actual usage</li></ul></li><li><p><strong>Content Selection</strong>:</p><ul><li>Choose focused, relevant knowledge bases</li><li>Avoid including too many sources (can dilute results)</li><li>Test with representative questions before publishing</li></ul></li><li><p><strong>Sharing Strategy</strong>:</p><ul><li>Create department-specific Blueprints for specialized needs</li><li>Use broader Blueprints for company-wide information</li><li>Regularly review access permissions</li></ul></li><li><p><strong>Conversation Starters</strong>:</p><ul><li>Create starters that address common user needs</li><li>Use action-oriented language</li><li>Include diverse examples to demonstrate capabilities</li></ul></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Issue</strong>: Blueprint name error message</p><ul><li>Names must be unique across the system</li><li>Try a more specific name or add a qualifier</li><li>Check for extra spaces that might affect validation</li></ul><p><strong>Issue</strong>: Imported Blueprint missing settings</p><ul><li>Some settings like groups and ownership must be reconfigured</li><li>Secure Blueprints cannot be exported/imported</li><li>Verify file format (.blueprint) is correct</li></ul><p><strong>Issue</strong>: Blueprint not appearing for users</p><ul><li>Check group assignments (users must belong to assigned groups)</li><li>Verify Blueprint is enabled</li><li>Check &quot;Quick List&quot; and &quot;Home Page&quot; settings based on expected visibility</li></ul><p><strong>Issue</strong>: Web page content not included in responses</p><ul><li>Verify URLs are correct and complete (including https://)</li><li>Pages may require authentication or block AI access</li><li>Some sites have anti-scraping measures that prevent access</li></ul><p><strong>Issue</strong>: Conversation starters not working</p><ul><li>Verify prompts are clear and specific</li><li>Check LaunchPad toggle is enabled for visible starters</li><li>Test prompts independently to verify expected behavior</li></ul><p><strong>Issue</strong>: Unexpected AI responses</p><ul><li>Review system instructions for clarity</li><li>Check that knowledge bases contain relevant information</li><li>Consider adjusting score threshold for more precise results</li><li>Test with different AI modes to compare results</li></ul><hr><p>For additional assistance with Blueprint configuration, please contact your system administrator or refer to the platform documentation.</p>',108)]))}const f=i(s,[["render",u]]);export{b as __pageData,f as default};
